<?php if(empty($data['order'])): ?>
  <div class="empty-state"><h3>We couldn't find that order</h3><a href="?page=orders">See all orders</a></div>
<?php else: $o=$data['order'];$steps=['pending_review','approved','out_for_delivery','delivered'];$done=array_search($o['status'],$steps,true); ?>
  <div class="page-heading"><div><span class="eyebrow">ORDER <?= '#'.(int)$o['id'] ?></span><h1>It's in good hands.</h1><p>Placed <?= e(date('M j, Y · g:i A',strtotime($o['created_at']))) ?> · We're keeping you in the loop.</p></div><a class="soft-button" href="?page=orders">← All orders</a></div>
  <div class="tracking-layout"><div class="panel tracking-panel">
    <div class="tracking-status <?= $o['status']==='rejected'?'status-rejected':'' ?>"><span class="status-icon"><?= $o['status']==='delivered'?'✓':($o['status']==='rejected'?'!':'✦') ?></span><div><span class="eyebrow">CURRENT STATUS</span><b id="order-live-status"><?= e(order_status_label($o['status'])) ?></b><?php if($o['status']==='pending_review'): ?><p>Our pharmacist is carefully checking your order.</p><?php elseif($o['status']==='approved'): ?><p>Your order is approved and being prepared with care.</p><?php elseif($o['status']==='out_for_delivery'): ?><p>Your rider is on the way. Keep your phone close.</p><?php elseif($o['status']==='delivered'): ?><p>Your delivery is complete. We hope you feel better soon.</p><?php elseif($o['status']==='rejected'): ?><p><?= e($o['rejection_note']) ?></p><?php endif; ?></div></div>
    <?php if($o['status']==='rejected'): ?><div class="rejection-box"><b>Pharmacist's note</b><p><?= e($o['rejection_note']) ?></p><span>Contact the pharmacy if you need help with your order.</span></div><?php else: ?>
      <div class="stepper"><?php foreach($steps as $i=>$step): $isCurrent=$step===$o['status'];$isDone=$done!==false&&$i<$done; ?><div class="step <?= $isCurrent?'current':($isDone?'complete':'') ?>"><div class="step-marker"><?= $isDone?'✓':($i+1) ?></div><div><b><?= e(order_status_label($step)) ?></b><span><?= ['Your order is in our queue','Your pharmacist approved it','Your rider is on the way','At your door'][$i] ?></span></div></div><?php if($i<count($steps)-1): ?><div class="step-connector <?= $isDone?'complete':'' ?>"></div><?php endif; endforeach; ?></div>
      <section class="live-map-section"><div class="live-map-heading"><span><b>Your delivery, live</b><small>Rider location refreshes automatically every 3 seconds.</small></span><span class="live-indicator"><i></i> LIVE</span></div><div class="tracking-rider-card"><div id="tracking-rider-avatar"><?= avatar_html($o['rider_name']??'MedDrop Rider',$o['rider_profile_photo']??null,'tracking-avatar') ?></div><div class="tracking-rider-identity"><b id="tracking-rider-name"><?= e($o['rider_name']??'Finding a rider') ?></b><span id="tracking-rider-status"><?= $o['rider_name']?e(order_status_label($o['status'])):'We’ll show your rider when they accept the delivery' ?></span></div><div class="eta-badges"><span><small>DISTANCE REMAINING</small><b id="distance-remaining">— km</b></span><span><small>ESTIMATED ARRIVAL</small><b id="arrival-estimate">— min</b></span></div></div><div id="customer-tracking-map" class="leaflet-map tracking-map" data-order-id="<?= (int)$o['id'] ?>" data-status="<?= e($o['status']) ?>" data-delivery-lat="<?= e((string)$o['delivery_lat']) ?>" data-delivery-lng="<?= e((string)$o['delivery_lng']) ?>" data-rider-lat="<?= e((string)$o['rider_lat']) ?>" data-rider-lng="<?= e((string)$o['rider_lng']) ?>" data-rider-name="<?= e($o['rider_name']??'') ?>" data-rider-photo="<?= e(avatar_url($o['rider_profile_photo']??null)) ?>" data-pharmacy-lat="<?= PHARMACY_LAT ?>" data-pharmacy-lng="<?= PHARMACY_LNG ?>"></div><div class="tracking-map-footer"><span>✚ Pharmacy</span><span>● Your location</span><span>➤ Rider</span><span class="route-source">Road route via OSRM</span></div></section>
    <?php endif; ?></div>
    <div class="panel order-summary"><div class="panel-heading"><div><b>Order summary</b><span><?= count($data['items']) ?> items</span></div></div><?php foreach($data['items'] as $item): ?><div class="summary-item"><span><b><?= e($item['medicine_name']) ?></b><small>Qty <?= (int)$item['quantity'] ?> × <?= money($item['unit_price']) ?></small></span><b><?= money($item['quantity']*$item['unit_price']) ?></b></div><?php endforeach; ?><div class="summary-divider"></div><div class="summary-item"><span>Subtotal</span><b><?= money($o['subtotal']) ?></b></div><?php if((float)$o['discount_amount']>0): ?><div class="summary-item discount-line"><span>Senior / PWD discount <?= $o['discount_verified']?'':'· pending review' ?></span><b>−<?= money($o['discount_amount']) ?></b></div><?php endif; ?><div class="summary-item total-line"><span>Total</span><b><?= money($o['total_amount']) ?></b></div><div class="summary-detail"><span>Delivery address</span><b><?= nl2br(e($o['delivery_address'])) ?></b></div><div class="summary-detail"><span>Payment</span><b><?= e($o['payment_method']) ?><?= $o['payment_reference']?' · '.e($o['payment_reference']):'' ?></b></div></div>
  </div>
<?php endif; ?>
